      SessionMessageListOrder? order,
      String? cursor,
      SessionMessageListType? type,
      RequestOptions? options}) async {
    final result = await transport.jsonRequest(
      method: 'GET',
      path: '/api/session/${Uri.encodeComponent(sessionID.toString())}/message',
      query: <String, Object?>{
        if (limit != null) 'limit': limit,
        if (order != null) 'order': order.wire,
        if (cursor != null) 'cursor': cursor,
        if (type != null) 'type': type.wire
      },
      options: options,
    );
    return SessionMessagesResponse.fromJson(asJsonMap(result));
  }
}

/// API resource `form`.
final class SessionFormResource {
  /// Creates the resource.
  SessionFormResource(this.transport);

  /// The shared HTTP transport.
  final OpenCodeTransport transport;

  /// List session forms - Retrieve pending forms for a session.
  Future<List<FormInfo>> list(
      {required String sessionID, RequestOptions? options}) async {
    final result = await transport.jsonRequest(
      method: 'GET',
      path: '/api/session/${Uri.encodeComponent(sessionID.toString())}/form',
      options: options,
    );
    return jsonList(asJsonMap(result)['data'],
        (item) => FormInfo.fromJson(asJsonMap(item)));
  }

  /// Create session form - Create a form for a session.
  Future<FormInfo> create(
      {required String sessionID,
      FormID? id,
      required String title,
      Map<String, Object?>? metadata,
      required List<FormField> fields,
      RequestOptions? options}) async {
    final result = await transport.jsonRequest(
      method: 'POST',
      path: '/api/session/${Uri.encodeComponent(sessionID.toString())}/form',
      body: <String, Object?>{
        if (id != null) 'id': id,
        'title': title,
        if (metadata != null) 'metadata': metadata,
        'fields': [for (final item in fields) item.toJson()]
      },
      options: options,
    );
    return FormInfo.fromJson(asJsonMap(asJsonMap(result)['data']));
  }

  /// Get session form - Retrieve a form and its current state for a session.
  Future<FormDetail> get(
      {required String sessionID,
      required FormID formID,
      RequestOptions? options}) async {
    final result = await transport.jsonRequest(
      method: 'GET',
      path:
          '/api/session/${Uri.encodeComponent(sessionID.toString())}/form/${Uri.encodeComponent(formID.toString())}',
      options: options,
    );
    return FormDetail.fromJson(asJsonMap(asJsonMap(result)['data']));
  }

  /// Cancel form - Cancel a pending form, optionally telling the asker why it was not answered.
  Future<void> cancel(
      {required String sessionID,
      required FormID formID,
      String? message,
      RequestOptions? options}) async {
    await transport.jsonRequest(
      method: 'DELETE',
      path:
          '/api/session/${Uri.encodeComponent(sessionID.toString())}/form/${Uri.encodeComponent(formID.toString())}',
      query: <String, Object?>{if (message != null) 'message': message},
      empty: true,
      successStatus: 204,
      options: options,
    );
  }

  /// Reply to form - Submit an answer to a pending form.
  Future<void> reply(
      {required String sessionID,
      required FormID formID,
      required Map<String, Object?> answer,
      RequestOptions? options}) async {
    await transport.jsonRequest(
      method: 'POST',
      path:
          '/api/session/${Uri.encodeComponent(sessionID.toString())}/form/${Uri.encodeComponent(formID.toString())}/reply',
      body: <String, Object?>{'answer': answer},
      empty: true,
      successStatus: 204,
      options: options,
    );
  }
}
